create table journeys(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,name text not null,channel_id int not null references channels,team_id int references teams,config jsonb not null,status text not null default 'draft' check(status in ('draft','active','paused','finished')),created_by int references users,created_at timestamptz not null default now());
create table journey_members(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,journey_id int not null references journeys,contact_id int not null references contacts,snapshot jsonb not null,step int not null default 0,state text not null default 'active' check(state in ('active','paused','completed','cancelled','replied')),due_at timestamptz not null default now(),awaiting_campaign_id int references campaigns,awaiting_bot_id bigint references bot_invocations,attempts int not null default 0,detail text,created_at timestamptz not null default now(),finished_at timestamptz);
create unique index journey_member_active on journey_members(journey_id,contact_id) where state in ('active','paused');
create index journey_due on journey_members(due_at) where state='active';
create table journey_events(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,journey_id int not null references journeys,member_id bigint references journey_members,step int,type text not null,detail text,actor_id int references users,at timestamptz not null default now());
alter table campaigns add column journey_member_id bigint references journey_members;
create index campaign_journey on campaigns(journey_member_id) where journey_member_id is not null;
do $$ declare r record;begin
 for r in select * from (values('journeys','channels,channel_id,teams,team_id,users,created_by'),('journey_members','journeys,journey_id,contacts,contact_id,campaigns,awaiting_campaign_id,bot_invocations,awaiting_bot_id'),('journey_events','journeys,journey_id,journey_members,member_id,users,actor_id')) v(t,a) loop
 execute format('alter table %I enable row level security',r.t);execute format('alter table %I force row level security',r.t);execute format($f$create policy tenant_iso on %I using(tenant_id=nullif(current_setting('app.tenant',true),'')::int) with check(tenant_id=nullif(current_setting('app.tenant',true),'')::int)$f$,r.t);
 execute format('create trigger fk_guard before insert or update on %I for each row execute function fk_guard(%s)',r.t,(select string_agg(quote_literal(x),',') from unnest(string_to_array(r.a,',')) x));end loop;
end $$;
create trigger campaign_journey_guard before insert or update on campaigns for each row execute function fk_guard('journey_members','journey_member_id');
